import { IsISO8601, IsObject, IsString, IsUUID, MaxLength } from 'class-validator';

// The envelope of one phone command (docs/phase-b-design.md section 5). The
// payload is validated separately by the handler for its type.
export class SyncCommandDto {
  // Generated by the phone; the key that makes processing idempotent.
  @IsUUID()
  command_id!: string;

  @IsString()
  @MaxLength(64)
  type!: string;

  // When the phone says it happened. More than 24 hours ahead is rejected.
  @IsISO8601({ strict: true })
  occurred_at!: string;

  @IsObject()
  payload!: Record<string, unknown>;
}
